#include <bits/stdc++.h>
typedef long long LL;
using namespace std;
#define rep(i,n) for(int i=0; i<n; i++)

template<int N>
struct MaxFlow {
    int head[N], total, current[N], dist[N], u, v, s, t, src, snk;
    struct Edge {
        int v, next, cap;
    } edges[111111];

    void add_edge(int u, int v, int cap) {
        edges[total] = {v, head[u], cap};
        head[u] = total++;
        edges[total] = {u, head[v], 0};
        head[v] = total++;
    }

    void init() {
        memset(head, -1, sizeof head);
        total = 0;
    }

    bool build_bfs() {
        memset(dist, -1, sizeof dist);
        memcpy(current, head, sizeof head);
        dist[src] = 0;
        queue<int> q;
        q.push(src);
        while(!q.empty()) {
            int u = q.front(); q.pop();
            for(int i = head[u]; i != -1; i = edges[i].next) {
                v = edges[i].v;
                if(dist[v] == -1 && edges[i].cap > 0) {
                    dist[v] = dist[u] + 1;
                    q.push(v);
                }
            }
        }
        return dist[snk] != -1;
    }

    int send_flow(int u, int flow) {
        if(u == snk) return flow;
        int total_flow = 0, pushed;
        for(int &i = current[u]; i != -1; i = edges[i].next) {
            v = edges[i].v;
            if(dist[v] == dist[u] + 1 && edges[i].cap > 0) {
                pushed = send_flow(v, min(flow - total_flow, edges[i].cap));
                if(pushed > 0) {
                    edges[i].cap -= pushed;
                    edges[i ^ 1].cap += pushed;
                    total_flow += pushed;
                    if(total_flow == flow) break;
                }
            }
        }
        if(total_flow == 0) dist[u] = -1;
        return total_flow;
    }

    int max_flow(int s, int t) {
        src = s; snk = t;
        int total_flow = 0;
        while(build_bfs()) {
            total_flow += send_flow(s, INT_MAX);
        }
        return total_flow;
    }
};

int n;
const int N = 15;
char grid[N][N], capsule[N][N];
int Z[N][N], S[N][N];
int dx[] = {-1,1,0,0};
int dy[] = {0,0,-1,1};

inline bool inside(int i, int j) {
    return i >= 0 && i < n && j >= 0 && j < n;
}

MaxFlow<210> flow;
int T;
const int INF = 1e9;

inline bool is_digit(char ch) {
    return ch >= '1' && ch <= '9';
}

void run_bfs(int x, int y, int dist_map[][N], bool mark) {
    int start_x = x, start_y = y;
    memset(dist_map, 0x3f, sizeof(int)*N*N);
    dist_map[x][y] = 0;
    queue<int> q;
    q.push(x);
    q.push(y);
    if(mark && is_digit(capsule[x][y])) {
        flow.add_edge(start_x * n + start_y, start_x * n + start_y + n * n, INF);
    }
    while(!q.empty()) {
        x = q.front(); q.pop();
        y = q.front(); q.pop();
        if(dist_map[x][y] == T) break;
        rep(o,4) {
            int xx = x + dx[o], yy = y + dy[o];
            if(inside(xx, yy) && dist_map[xx][yy] == 0x3f3f3f3f && capsule[xx][yy] != 'Y') {
                if(Z[xx][yy] > dist_map[x][y] + 1 || (Z[xx][yy] == dist_map[x][y] + 1 && is_digit(capsule[xx][yy]))) {
                    dist_map[xx][yy] = dist_map[x][y] + 1;
                    if(mark && is_digit(capsule[xx][yy])) {
                        flow.add_edge(start_x * n + start_y, xx * n + yy + n * n, INF);
                    }
                    if(Z[xx][yy] > dist_map[x][y] + 1 || !mark) {
                        q.push(xx);
                        q.push(yy);
                    }
                }
            }
        }
    }
}

int main() {
    int x, y;
    scanf("%d%d", &n, &T);
    int s_node = n * n * 2, t_node = s_node + 1;
    flow.init();
    rep(i, n) {
        scanf("%s", grid[i]);
        rep(j, n) {
            if(grid[i][j] == 'Z') {
                x = i; y = j;
            }
        }
    }
    rep(i, n) {
        scanf("%s", capsule[i]);
        rep(j, n) {
            if(is_digit(capsule[i][j])) {
                flow.add_edge(i * n + j + n * n, t_node, capsule[i][j] - '0');
            }
        }
    }
    run_bfs(x, y, Z, false);
    rep(i, n) {
        rep(j, n) {
            if(is_digit(grid[i][j])) {
                flow.add_edge(s_node, i * n + j, grid[i][j] - '0');
                run_bfs(i, j, S, true);
            }
        }
    }
    printf("%d\n", flow.max_flow(s_node, t_node));
    return 0;
}
